projects.push(p('planik-bileca-hybrid','Planik Hybrid Wind and Solar Project','Bosnia and Herzegovina','B&B Sunce Vjetar d.o.o. · beneficial ownership requires official registry confirmation','80 MW solar + 36 MW wind','Ownership verification','Planik is a Bileća hybrid renewable project. B&B Sunce Vjetar is confirmed as the legal project company and concessionaire in official grid and concession records. Public sources identify Nedeljko Babić and Ljubiša Bošković as current company owners, while earlier consortium reporting also named BIG Energia Holdings and BIG Shopping Centers/Mega Or. Ultimate ownership remains unresolved pending an official court-register extract, shareholder register and beneficial-owner declaration.','https://www.nosbih.ba/bs/dokumenti/registri/bilansirani-korisnici/',{stage:'Concessioned and grid-registered · RTB claim requires documentary refresh',partnership:'Equity/acquisition opportunity reported by intermediary · seller mandate not independently verified',location:'Bileća, Republika Srpska, Bosnia and Herzegovina · Planik / Korita / Meka Gruda area',technology:'Hybrid renewable project: 80 MW solar and 36 MW onshore wind; optional BESS reported by intermediary',financials:[['Reported CAPEX','EUR 125 million in the intermediary teaser; not independently verified.'],['Concession','Official records identify B&B Sunce Vjetar as concessionaire for Planik solar and wind projects. Public sources report approximately 27–27.5-year terms; official records require reconciliation.'],['Grid','NOSBiH register lists SE and VE Planik at 80 + 36 MW. The current register notes a wind connection-contract application dated 16 April 2026.'],['PPA','Intermediary material reports multiple non-binding state/private offers and negotiation. No signed government PPA has been independently verified.'],['Commercial stage','Seller states RTB, but official 2024 reporting described the projects as preparatory. Treat RTB as unverified until current permits and grid agreement are supplied.']],history:[['2022-12-07','Republika Srpska concession agreements reported for Planik solar and wind.'],['2023-07','Montenegro Ministry recorded Espoo cross-border consultation for Planik wind, 39.6 MW.'],['2024-03-26','NOSBiH register recorded B&B Sunce Vjetar for SE and VE Planik, 80 + 36 MW.'],['2026-04-16','NOSBiH register notes an application for the VE Planik connection contract.'],['2026-10-21','Ownership audit: legal concessionaire confirmed; ultimate ownership remains unresolved.']],contacts:[c('B&B Sunce Vjetar d.o.o.','Legal project company / concessionaire','Primary legal and project-company route; request official shareholder extract, permits, grid agreement and seller authority','', '', 'Official project-company identity in NOSBiH; direct corporate contact not independently verified','https://www.nosbih.ba/bs/dokumenti/registri/bilansirani-korisnici/'),c('Nedeljko Babić','Director; reported current owner','Director and reported ownership route; current shareholding percentage requires official register confirmation','', '', 'Commercial registry report; not an official ownership extract','https://www.companywall.ba/firma/bb-sunce-vjetar-doo/MMxBCienq',['+387 61 789 536']),c('Ljubiša Bošković','Reported current owner; Sistem-MNE principal','Reported ownership route and renewable-project sponsor connection; current shareholding percentage requires official register confirmation','info@sistem-mne.com','https://me.linkedin.com/in/ljubisa-boskovic-8368028a','Public company route and LinkedIn; not proof of current B&B shareholding','https://sistem-mne.com/o-nama',['+382 20 215 250']),c('BIG Energia Holdings / BIG Shopping Centers / Mega Or','Reported consortium / investor route','Named in 2022 public reporting; current equity position and authority require official B&B ownership records','', '', 'Historical public reporting; not current ownership proof','https://www.akta.ba/investicije/projekti/154744/big-shopping-centers-dobio-medunarodni-tender-za-izgradnju-vjetro-solarnog-projekta-u-bileci'),c('Republika Srpska Concessions Commission','Concession authority','Official route for concession number, term, amendments, assignment and compliance status','', '', 'Official authority source','https://koncesije-rs.org/registar_koncesija/'),c('Ministry of Energy and Mining, Republika Srpska','Concession grantor / energy authority','Official route for signed concession agreements, energy permits and current project status','', '', 'Official authority source','https://www.vladars.net/sr-SP-Cyrl/Vlada/Ministarstva/mper/Pages/default.aspx'),c('NOSBiH','Transmission-system / balancing register','Official route for balancing registration and current grid-stage evidence','', '', 'Official register updated 14 October 2026','https://www.nosbih.ba/bs/dokumenti/registri/bilansirani-korisnici/'),c('Elektroprenos BiH','Transmission-grid connection authority','Official route for connection request, study, agreement, capacity, costs and energisation status','', '', 'Project-specific agreement not obtained','https://www.elprenos.ba/'),c('DERK / SERC','State electricity regulator','Official route for approved generation plans and regulatory status','', '', 'Official generation-plan source','https://www.derk.ba/'),c('Municipality of Bileća','Municipal planning and local authority','Route for regulatory plan, land-use planning, public notices and municipal approvals','', '', 'Certified municipal project file not obtained','https://www.bileca.info/'),c('Ministry of Spatial Planning, Construction and Ecology, Republika Srpska','Planning and environmental authority','Route for environmental permits, location conditions, appeals and permit status','', '', 'Certified permit decisions not obtained','https://www.vladars.net/sr-SP-Cyrl/Vlada/Ministarstva/mgr/Pages/default.aspx'),c('Montenegro Ministry of Ecology, Spatial Planning and Urbanism','Espoo / cross-border environmental route','Cross-border consultation record for Planik wind project, 39.6 MW','brankica.cmiljanovic@mepg.gov.me','', 'Official Espoo consultation contact','https://www.gov.me/en/documents/5fece58f-f622-44b6-a325-c93c63a1c8f2')],sources:[{title:'NOSBiH balanced-users register',url:'https://www.nosbih.ba/bs/dokumenti/registri/bilansirani-korisnici/',date:'Register updated 14 October 2026'},{title:'DERK/NOSBiH Indicative Generation Development Plan 2025–2034',url:'https://www.derk.ba/DocumentsPDFs/Indikativni-plan-razvoja-proizvodnje-2025-2034.pdf',date:'June 2024'},{title:'Republika Srpska Concessions Commission register',url:'https://koncesije-rs.org/registar_koncesija/',date:'Official concession register'},{title:'Republika Srpska 2024 concessions report',url:'https://koncesije-rs.org/wp-content/uploads/2025/08/Izvjestaj-2024.pdf',date:'2024 report published 2025'},{title:'B&B Sunce Vjetar commercial registry summary',url:'https://www.companywall.ba/firma/bb-sunce-vjetar-doo/MMxBCienq',date:'Commercial database; not an official extract'},{title:'Consortium reporting',url:'https://www.akta.ba/investicije/projekti/154744/big-shopping-centers-dobio-medunarodni-tender-za-izgradnju-vjetro-solarnog-projekta-u-bileci',date:'November 2022'},{title:'Montenegro Espoo consultation notice',url:'https://www.gov.me/en/documents/5fece58f-f622-44b6-a325-c93c63a1c8f2',date:'7 July 2023'},{title:'Republika Srpska cumulative environmental impacts report',url:'https://vladars.rs/sr-SP-Cyrl/Vlada/Ministarstva/mgr/Documents/%D0%9F%D0%9F%20%D0%92%D0%95%20%D0%9B%D0%B5%D0%BE%D1%82%D0%B0%D1%80%20%D0%A2%D1%80%D0%B5%D0%B1%D0%B8%D1%9A%D0%B5_567862533.pdf',date:'Official environmental-planning reference'}],gaps:['Obtain an official current court/company-register extract for B&B Sunce Vjetar.','Obtain the shareholder register, beneficial-owner declaration and ownership percentages.','Reconcile Babić/Bošković current registry reporting against the historical BIG Energia / BIG Shopping / Mega Or consortium reports.','Obtain signed concession agreements, amendments and any transfer or assignment approvals.','Obtain certified environmental, location, construction and energy-permit decisions from the competent RS authorities.','Obtain the current Elektroprenos connection study/agreement and confirm whether the 400 kV route and substation works are committed.','Obtain executed PPA/offtake evidence; current public material supports negotiation/non-binding offers only.','Obtain the intermediary’s written seller mandate and identify the transaction SPV being offered.'],next:'Request the official ownership extract, shareholder/UBO package, concession documents, environmental/location permits, current grid agreement and signed PPA evidence before treating the project as owner-confirmed or RTB.'}));
